<?php
declare(strict_types=1);
require dirname(__DIR__).'/private/CatalogStore.php';require dirname(__DIR__).'/private/Assortments.php';require dirname(__DIR__).'/private/AvitoFeed.php';
use BotanikArt\{CatalogStore,Assortments,AvitoFeed};
function agTest($v,$why){if(!$v)throw new RuntimeException($why);}
$root=sys_get_temp_dir().'/ba-assortments-'.bin2hex(random_bytes(6));mkdir($root.'/data',0700,true);mkdir($root.'/assets/uploads/catalogue',0700,true);mkdir($root.'/catalogue',0700,true);copy(dirname(__DIR__,2).'/catalogue/avito-schema.json',$root.'/catalogue/avito-schema.json');$photo='assets/uploads/catalogue/'.str_repeat('a',32).'.jpg';file_put_contents($root.'/'.$photo,'fixture');file_put_contents($root.'/data/catalog.json',json_encode(['products'=>[['id'=>'flowwow-fixture','source'=>'flowwow','title'=>'Fixture','price'=>500,'description'=>'Fixture','catalogGroup'=>'plant','status'=>'ready','available'=>true,'images'=>[$photo]]]]));
try{$s=new CatalogStore($root.'/api/.private/catalogue',$root.'/data/catalog.json');$s->db->exec("UPDATE products SET hidden=1 WHERE id='flowwow-fixture'");$a=new Assortments($s);$a->migrate();$g=$a->create('Растения');$ids=[];foreach(['Первое','Второе'] as $title)$ids[]=$s->save(['title'=>$title,'description'=>'Описание '.$title,'price'=>500,'status'=>'ready','catalogGroup'=>'plant','source'=>'manual','images'=>[$photo],'assortmentId'=>$g,'channels'=>['avito'=>['enabled'=>true,'configure'=>true]]]);
 agTest(count($s->publicCatalog()['products'])===2,'Container leaked on storefront');agTest((int)$s->db->query("SELECT count(*) FROM publication_jobs WHERE channel='avito'")->fetchColumn()===0,'Adding member queued publication');
 $group=$a->list()[0];$a->save(array_merge($group,['description'=>'Общее описание','price'=>500,'category'=>'rasteniya_drugoe','attributes'=>['AdType'=>'Товар от производителя'],'images'=>[$photo],'useFirst'=>false]));$group=$a->list()[0];$a->publish($g,$group['version']);$f=new AvitoFeed(json_decode(file_get_contents($root.'/catalogue/avito-schema.json'),true));$xml=$f->render($s->all(true),'https://botanikart.ru');agTest(substr_count($xml,'<Ad>')===1,'More than one listing for assortment');agTest(str_contains($xml,'Общее описание'),'Wrong description');
 $member=array_values(array_filter($s->all(true),fn($p)=>$p['id']===$ids[0]))[0];$member['description']='Изменённое индивидуальное описание';$s->save($member);agTest($f->render($s->all(true),'https://botanikart.ru')===$xml,'Member save mutated published snapshot');
 agTest($a->list()[0]['changed'],'Member change not marked');$group=$a->list()[0];$a->save(array_merge($group,['useFirst'=>true]));$group=$a->list()[0];$a->publish($g,$group['version']);agTest(str_contains($f->render($s->all(true),'https://botanikart.ru'),'Изменённое индивидуальное описание'),'First description not applied');agTest(!empty($a->publish($g,$group['version'])['unchanged']),'Unchanged publish not idempotent');
 $member=array_values(array_filter($s->all(true),fn($p)=>$p['id']===$ids[0]))[0];$s->archive($member['id'],$member['version']);agTest(substr_count($f->render($s->all(true),'https://botanikart.ru'),'<Ad>')===1,'Deleting member removed published assortment');
 $a->attach($ids[1],'');agTest(!$s->channels($ids[1])['avito']['enabled']&&$s->channels($ids[1])['avito']['externalId']==='','Detach retained old listing identity');

 $s->db->exec("DELETE FROM metadata WHERE name='assortments:v1'");
 $items=[];foreach(['a','b'] as $v)$items[]=['source'=>'avito','avitoItemId'=>'8388087362','avitoVariant'=>$v,'title'=>'Imported '.$v,'description'=>'Old text','price'=>400,'catalogGroup'=>'plant','status'=>'ready','images'=>[$photo],'url'=>'https://www.avito.ru/8388087362'];$s->importBatch($items,true);$a->migrate();$before=count($a->list());$a->migrate();agTest(count($a->list())===$before,'Migration duplicated groups');
 $legacyGroup=array_values(array_filter($a->list(),fn($g)=>$g['externalId']==='8388087362'))[0];agTest(count($legacyGroup['members'])===2&&!$legacyGroup['changed'],'Migration changed existing assortment');
 $a->save(array_merge($legacyGroup,['description'=>'New common text','attributes'=>array_merge($legacyGroup['attributes'],['AdType'=>'Товар от производителя'])]));$legacyGroup=array_values(array_filter($a->list(),fn($g)=>$g['externalId']==='8388087362'))[0];$a->publish($legacyGroup['id'],$legacyGroup['version']);$xml=$f->render($s->all(true),'https://botanikart.ru');$legacy=json_decode(file_get_contents(dirname(__DIR__).'/private/avito-legacy.json'),true)['8388087362'];agTest(str_contains($xml,'<Id>'.$legacy['id'].'</Id><AvitoId>8388087362</AvitoId>'),'Migration changed original feed identity');agTest(str_contains($xml,'New common text'),'Legacy defaults overwrote group draft');
 $job=$s->db->query("SELECT revision FROM publication_jobs WHERE channel='avito' AND product_id=".$s->db->quote($legacyGroup['id']))->fetchColumn();$a->save(array_merge($legacyGroup,['description'=>'Another shared revision']));$updated=array_values(array_filter($a->list(),fn($g)=>$g['id']===$legacyGroup['id']))[0];$a->publish($updated['id'],$updated['version']);agTest($job!==$s->db->query("SELECT revision FROM publication_jobs WHERE channel='avito' AND product_id=".$s->db->quote($legacyGroup['id']))->fetchColumn(),'Shared description change did not queue a new revision');
 $a->disable($legacyGroup['id']);agTest(!str_contains($f->render($s->all(true),'https://botanikart.ru'),'<AvitoId>8388087362</AvitoId>'),'Disabled assortment remained in feed');
 echo "Assortment checks passed: drafts, frozen publication, single listing, explicit first-description, idempotency, member deletion and detach.\n";
}finally{$it=new RecursiveIteratorIterator(new RecursiveDirectoryIterator($root,FilesystemIterator::SKIP_DOTS),RecursiveIteratorIterator::CHILD_FIRST);foreach($it as $f)$f->isDir()?rmdir($f->getPathname()):unlink($f->getPathname());rmdir($root);}
